// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address to, uint256 tokenId, bytes calldata data) public {
        vm.assume(to != address(0));
        // deploy minimal safe mint receiver that calls back into c's onERC721Received
        Receiver rec = new Receiver();
        // the actual safeMint logic uses _safeMint which internally calls _mint and then checks the receiver's
        // onERC721Received return value.  Here we just test a direct call to the public onERC721Received entry.
        // The reference returns IERC721TokenReceiver.onERC721Received.selector (0x150b7a02).
        // The mutant returns 0xdeadbeef.
        bytes4 expected = bytes4(keccak256("onERC721Received(address,address,uint256,bytes)"));
        bytes4 got = c.onERC721Received(address(this), to, tokenId, data);
        assertEq(got, expected, "ERC721TokenReceiver.onERC721Received should return standard selector");
    }
}

contract Receiver {
    fallback() external payable {}
}

