pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, uint16 _newFeeRate, uint128 _amount) public {
        vm.assume(_feeRate <= 5000);
        vm.assume(_feeRate > 0);
        vm.assume(_newFeeRate <= 5000);
        vm.assume(_newFeeRate > 0);
        vm.assume(_feeRate != _newFeeRate);
        vm.assume(_virtualNftReserves > 0);
        vm.assume(_amount > 0 && _amount < _virtualNftReserves);

        address dev = address(0x1234);
        c.initialize(address(0), address(0), _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, bytes32(0), false, false);

        vm.prank(dev);
        c.setFeeRate(_newFeeRate);

        ( , uint256 feeAfterInit, ) = c.buyQuote(_amount);
        ( , uint256 feeAfterSet, ) = c.buyQuote(_amount);

        assertTrue(feeAfterInit != feeAfterSet);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(uint128 virtualBaseTokenReserves, uint128 virtualNftReserves, uint56 changeFee, uint16 _feeRate, uint16 protocolFeeRate, uint128 inputAmount) public {
        vm.assume(_feeRate > 0 && _feeRate <= 5000);
        vm.assume(protocolFeeRate <= 10000);
        vm.assume(inputAmount > 0 && inputAmount < virtualBaseTokenReserves);
        vm.assume(virtualNftReserves > 0 && virtualBaseTokenReserves > 0);

        // Deploy a mock factory that returns the fuzzed protocolFeeRate
        FactoryMock factoryMock = new FactoryMock();
        factoryMock.setProtocolFeeRate(protocolFeeRate);

        // Deploy a fresh C with the mock factory address
        c = new C(address(factoryMock), address(this), address(this));

        // Initialize with fuzzed parameters
        c.initialize(
            address(0), // baseToken = ETH (address(0))
            address(0x1234), // nft (dummy)
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            _feeRate,
            bytes32(0), // merkleRoot
            false, // useStolenNftOracle
            false  // payRoyalties
        );

        // Call sellQuote and check that when feeRate > 0, feeAmount > 0
        (, uint256 feeAmount, ) = c.sellQuote(inputAmount);
        assertTrue(feeAmount > 0);
    }
}

contract FactoryMock {
    uint16 public protocolFeeRate;
    function setProtocolFeeRate(uint16 _rate) external { protocolFeeRate = _rate; }
    function ownerOf(uint256) external view returns (address) { return address(0); }
}
